const drafts=new Map();let activeAction=0,autoTimer,resultRevision=0;
const examples={json:'{"project":"ToolHub","language":"Tiếng Việt","tools":["JSON","Base64"],"ready":true}',base64:'Xin chào Việt Nam!',url:'https://example.com/tìm kiếm?q=công cụ',words:'ToolHub giúp bạn xử lý những công việc nhỏ mỗi ngày.\nDán nội dung và xem thống kê tại đây.',case:'xin chào, đây là ToolHub',slug:'10 công cụ hữu ích dành cho lập trình viên',color:'#236b52',timestamp:'2026-10-19T09:00:00+07:00',hash:'Xin chào Việt Nam!',html:'<button title="Chào bạn">Lưu & tiếp tục</button>',radix:'255',query:'https://example.com/search?q=công+cụ&tag=dev&tag=design',emails:'Liên hệ: dev@example.com, DESIGN@example.org. Gửi lại cho dev@example.com.',lines:'Thiết kế\nLập trình\nThiết kế\n\nViết nội dung'};
function rememberDraft(){if(!current)return;drafts.set(current.id,{fields:[...$('#fields').querySelectorAll('input,textarea,select')].map(el=>[el.id,el.type==='checkbox'?el.checked:el.value]),output:$('#output').value,status:$('#status').textContent,error:$('#status').dataset.error==='true',action:activeAction,auto:$('#autoRun').checked});}
function syncResult(){const value=$('#output').value;['copy','download','showResult'].forEach(id=>$('#'+id).disabled=!value);$('#reuse').disabled=!value||!$('#fields textarea');$('#reuse').hidden=!$('#fields textarea');$('#resultMeta').textContent=value?`${Array.from(value).length.toLocaleString('vi-VN')} ký tự · ${value.split('\n').length} dòng`:'Chưa có kết quả';$('#fields').querySelectorAll('input,textarea,select').forEach(el=>el.setAttribute('aria-invalid',$('#status').dataset.error==='true'?'true':'false'));}
function chooseAction(index){activeAction=index;$('#actions').querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('chosen',i===index);b.setAttribute('aria-pressed',String(i===index))});}
function runAction(){const button=$('#actions').children[activeAction];if(button)button.click();}
function openTool(id){++resultRevision;clearTimeout(autoTimer);rememberDraft();const draft=drafts.get(id);prepareTool(id);const pane=document.querySelector('.input-pane'),area=document.querySelector('.action-area');if(id==='password')pane.insertBefore(area,$('#fields'));else pane.append(area);pane.querySelector('h3').textContent=id==='password'?'Tùy chọn tạo mật khẩu':'Đầu vào';$('#toolSelect').value=id;$('#status').dataset.error='false';$('#status').style.color='';activeAction=draft?.action||0;const random=['uuid','password','lorem'].includes(id);$('#autoRun').closest('label').hidden=random;$('#autoRun').checked=draft?.auto??['words','slug','color','percent'].includes(id);$('#example').hidden=random;$('#clear').hidden=random;
const numeric=$('#amount');if(numeric){numeric.min=1;numeric.max=100;numeric.step=1;}
$('#fields').querySelectorAll('input,textarea,select').forEach(el=>{el.setAttribute('aria-describedby','status');el.spellcheck=false;el.addEventListener('input',()=>{++resultRevision;clearTimeout(autoTimer);$('#output').value='';$('#status').textContent='';$('#status').dataset.error='false';syncResult();rememberDraft();if(current.id==='password')updatePasswordSummary();if($('#autoRun').checked)autoTimer=setTimeout(()=>{if(el.value.trim())runAction()},300)});el.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();clearTimeout(autoTimer);runAction()}})});
$('#actions').querySelectorAll('button').forEach((button,i)=>{const handler=button.onclick;button.onclick=()=>{clearTimeout(autoTimer);chooseAction(i);handler()}});chooseAction(activeAction);
if(draft){draft.fields.forEach(([key,value])=>{const el=$('#'+key);if(el){if(el.type==='checkbox')el.checked=value;else el.value=value}});$('#output').value=draft.output;$('#status').textContent=draft.status;$('#status').dataset.error=String(draft.error);$('#status').style.color=draft.error?'#b14e3e':'';}syncResult();if(id==='password')setupPasswordControls();
if(!draft&&(random||['percent','color','timestamp'].includes(id)))runAction();$('#dialog').scrollTop=0;$('#fields').querySelector('textarea,input')?.focus({preventScroll:true});}
$('#toolSelect').innerHTML=categories.slice(1).map(category=>`<optgroup label="${category}">${tools.filter(t=>t.cat===category).map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</optgroup>`).join('');$('#toolSelect').onchange=e=>openTool(e.target.value);
$('#example').onclick=()=>{clearTimeout(autoTimer);if(current.id==='radix'){$('#input').value='255';$('#fromBase').value=10;$('#toBase').value=16}else if(current.id==='percent'){$('#part').value=25;$('#total').value=200}else $('#input').value=examples[current.id]||'';chooseAction(0);runAction();$('#fields').querySelector('textarea,input')?.focus({preventScroll:true})};
$('#clear').onclick=()=>{++resultRevision;clearTimeout(autoTimer);$('#fields').querySelectorAll('input,textarea,select').forEach(el=>el.value='');$('#output').value='';$('#status').textContent='';$('#status').dataset.error='false';syncResult();rememberDraft();$('#fields').querySelector('textarea,input')?.focus({preventScroll:true})};
$('#autoRun').onchange=()=>{rememberDraft();clearTimeout(autoTimer);if($('#autoRun').checked&&$('#fields').querySelector('input,textarea')?.value.trim())runAction()};
$('#reuse').onclick=()=>{clearTimeout(autoTimer);const input=$('#fields textarea');if(!input)return;input.value=$('#output').value;$('#output').value='';$('#status').textContent='Đã chuyển kết quả sang đầu vào. Chọn thao tác tiếp theo.';$('#status').dataset.error='false';$('#status').style.color='';syncResult();rememberDraft();input.focus({preventScroll:true})};
$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([$('#output').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`toolhub-${current.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#dialog').addEventListener('close',()=>{++resultRevision;clearTimeout(autoTimer);rememberDraft();document.querySelector(`[data-open="${current?.id}"]`)?.focus({preventScroll:true})});
$('#resetFilters').onclick=()=>{$('#search').value='';category=categories[0];view='all';render();$('#search').focus()};

$('#showResult').onclick=()=>document.querySelector('.output-pane').scrollIntoView({block:'start'});

function checkbox(id,label,checked=true){return `<label class="option-row" for="${id}"><input type="checkbox" id="${id}" ${checked?'checked':''}><span>${label}</span></label>`}
function passwordFields(){return `<div class="password-presets" aria-label="Cấu hình nhanh"><span>Cấu hình nhanh</span><div><button data-preset="strong">Đầy đủ ký tự · 20</button><button data-preset="readable">Dễ đọc · 16</button><button data-preset="pin">PIN · 6 số</button></div></div><div class="number-options">${field('pwdLength','Độ dài (4–128 ký tự)',20,'number')}${field('pwdCount','Số mật khẩu (1–50)',1,'number')}</div><fieldset class="password-group"><legend>Nhóm ký tự</legend>${checkbox('pwdUpper','Chữ hoa (A–Z)')}${checkbox('pwdLower','Chữ thường (a–z)')}${checkbox('pwdDigits','Chữ số (0–9)')}${checkbox('pwdSymbols','Ký hiệu đặc biệt')}${field('pwdCustomSymbols','Ký hiệu được phép',ToolHubLogic.symbols)}</fieldset><fieldset class="password-group"><legend>Tùy chọn bổ sung</legend>${checkbox('pwdAmbiguous','Bỏ ký tự dễ nhầm: I, l, 1, O, 0, o và dấu nháy')}${checkbox('pwdEvery','Có ít nhất một ký tự từ mỗi nhóm đã chọn')}${checkbox('pwdUnique','Không lặp ký tự trong từng mật khẩu',false)}${field('pwdExclude','Loại thêm các ký tự này (tùy chọn)','')}</fieldset><p class="password-summary" id="passwordSummary" role="status"></p><p class="password-note">Tạo ngẫu nhiên bằng bộ sinh mật mã của trình duyệt. Mỗi mật khẩu nằm trên một dòng.</p>`}
function readPasswordOptions(){return {length:$('#pwdLength').value,count:$('#pwdCount').value,upper:$('#pwdUpper').checked,lower:$('#pwdLower').checked,digits:$('#pwdDigits').checked,symbols:$('#pwdSymbols').checked,customSymbols:$('#pwdCustomSymbols').value,ambiguous:$('#pwdAmbiguous').checked,everyGroup:$('#pwdEvery').checked,unique:$('#pwdUnique').checked,exclude:$('#pwdExclude').value}}
function updatePasswordSummary(){if(current?.id!=='password')return;$('#pwdCustomSymbols').disabled=!$('#pwdSymbols').checked;try{const c=ToolHubLogic.passwordConfig(readPasswordOptions());$('#passwordSummary').textContent=`${c.count} mật khẩu × ${c.length} ký tự · Bộ ${c.pool.length} ký tự được phép`;$('#passwordSummary').classList.remove('invalid')}catch(e){$('#passwordSummary').textContent=e.message;$('#passwordSummary').classList.add('invalid')}}
function setupPasswordControls(){for(const [id,min,max] of [['pwdLength',4,128],['pwdCount',1,50]]){const el=$('#'+id);el.min=min;el.max=max;el.step=1}$('#pwdCustomSymbols').maxLength=94;$('#pwdExclude').maxLength=128;$('#fields').querySelectorAll('[data-preset]').forEach(button=>button.onclick=()=>{++resultRevision;const preset=button.dataset.preset;$('#pwdLength').value=preset==='pin'?6:preset==='readable'?16:20;for(const id of ['pwdUpper','pwdLower','pwdDigits','pwdSymbols'])$('#'+id).checked=preset==='pin'?id==='pwdDigits':preset==='readable'?id!=='pwdSymbols':true;$('#pwdCustomSymbols').value=ToolHubLogic.symbols;$('#pwdAmbiguous').checked=preset!=='pin';$('#pwdEvery').checked=true;$('#pwdUnique').checked=false;$('#pwdExclude').value='';updatePasswordSummary();rememberDraft();runAction()});updatePasswordSummary()}
function readQuery(){let s=val().trim();if(!s)throw Error('Nhập URL đầy đủ hoặc chuỗi tham số, ví dụ ?q=toolhub&lang=vi.');if(/^[a-z][a-z0-9+.-]*:\/\//i.test(s)){let url;try{url=new URL(s)}catch{throw Error('URL chưa hợp lệ. Hãy dùng URL đầy đủ hoặc chuỗi ?key=value.')}return url.searchParams}if(s.startsWith('?'))s=s.slice(1);return new URLSearchParams(s.split('#')[0])}
